Optimize this Node.js Express API for better performance and maintainability. const express = require("express");

const app = express();
app.use(express.json());

const users = [
    { id: 1, name: "Ashraf", email: "ashraf@example.com" },
    { id: 2, name: "Rahul", email: "rahul@example.com" },
    { id: 3, name: "Priya", email: "priya@example.com" }
];

// Get users by repeatedly filtering the entire array
app.get("/users", (req, res) => {
    let result = [];

    for (let i = 0; i < users.length; i++) {
        const matches = users.filter(user => user.id === users[i].id);

        for (let j = 0; j < matches.length; j++) {
            result.push(matches[j]);
        }
    }

    res.json(result);
});

// Search user inefficiently
app.get("/users/search", (req, res) => {
    const email = req.query.email;

    let result = [];

    for (let i = 0; i < users.length; i++) {
        const matches = users.filter(user => user.email === email);

        for (let j = 0; j < matches.length; j++) {
            result.push(matches[j]);
        }
    }

    res.json(result);
});

app.listen(3000, () => {
    console.log("Server running on port 3000");
